/// A message returned to Dart from the local database.
class StoredMessage {
  final PlatformInt64 id;
  final String peerId;
  final String text;
  final bool isMine;
  final PlatformInt64 timestamp;
  final String? signature;
  final String? publicKey;
  final String? messageId;
  final PlatformInt64? editedAt;
  final PlatformInt64? hiddenAt;
  final String? replyToMid;
  final String? fileId;

  /// Link preview for the first URL in this message (Phase 6.75).
  final LinkPreviewRef? linkPreview;

  const StoredMessage({
    required this.id,
    required this.peerId,
    required this.text,
    required this.isMine,
    required this.timestamp,
    this.signature,
    this.publicKey,
    this.messageId,
    this.editedAt,
    this.hiddenAt,
    this.replyToMid,
    this.fileId,
    this.linkPreview,
  });

  @override
  int get hashCode =>
      id.hashCode ^
      peerId.hashCode ^
      text.hashCode ^
      isMine.hashCode ^
      timestamp.hashCode ^
      signature.hashCode ^
      publicKey.hashCode ^
      messageId.hashCode ^
      editedAt.hashCode ^
      hiddenAt.hashCode ^
      replyToMid.hashCode ^
      fileId.hashCode ^
      linkPreview.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is StoredMessage &&
          runtimeType == other.runtimeType &&
          id == other.id &&
          peerId == other.peerId &&
          text == other.text &&
          isMine == other.isMine &&
          timestamp == other.timestamp &&
          signature == other.signature &&
          publicKey == other.publicKey &&
          messageId == other.messageId &&
          editedAt == other.editedAt &&
          hiddenAt == other.hiddenAt &&
          replyToMid == other.replyToMid &&
          fileId == other.fileId &&
          linkPreview == other.linkPreview;
}

