/// A user profile returned to Dart.
class UserProfile {
  final String peerId;
  final String displayName;
  final String status;
  final String aboutMe;
  final PlatformInt64 updatedAt;
  final Uint8List? avatarBytes;
  final Uint8List? bannerBytes;
  final String twitchUsername;

  /// Showcase board JSON (profile blocks; empty = no board).
  final String showcaseBoard;

  /// Avatar frame ID (issue #54): `""` = none, `"b:<hue>"` = built-in, 64-hex = an
  /// asset-rail blob hash pulled on demand.
  final String avatarFrame;

  /// Asset-rail hash of this person's ANIMATED avatar, `""` = still only.
  /// `avatar_bytes` above is the STILL companion the animation is painted over.
  final String avatarAnim;

  /// Asset-rail hash of this person's ANIMATED banner; `""` = still only.
  final String bannerAnim;

  /// Support credentials: the verified JSON array as stored, `""` for none. A renderer
  /// lights a mark next to art whose hash is in an entry's `parts` and is worn.
  final String supportCreds;

  const UserProfile({
    required this.peerId,
    required this.displayName,
    required this.status,
    required this.aboutMe,
    required this.updatedAt,
    this.avatarBytes,
    this.bannerBytes,
    required this.twitchUsername,
    required this.showcaseBoard,
    required this.avatarFrame,
    required this.avatarAnim,
    required this.bannerAnim,
    required this.supportCreds,
  });

  @override
  int get hashCode =>
      peerId.hashCode ^
      displayName.hashCode ^
      status.hashCode ^
      aboutMe.hashCode ^
      updatedAt.hashCode ^
      avatarBytes.hashCode ^
      bannerBytes.hashCode ^
      twitchUsername.hashCode ^
      showcaseBoard.hashCode ^
      avatarFrame.hashCode ^
      avatarAnim.hashCode ^
      bannerAnim.hashCode ^
      supportCreds.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UserProfile &&
          runtimeType == other.runtimeType &&
          peerId == other.peerId &&
          displayName == other.displayName &&
          status == other.status &&
          aboutMe == other.aboutMe &&
          updatedAt == other.updatedAt &&
          avatarBytes == other.avatarBytes &&
          bannerBytes == other.bannerBytes &&
          twitchUsername == other.twitchUsername &&
          showcaseBoard == other.showcaseBoard &&
          avatarFrame == other.avatarFrame &&
          avatarAnim == other.avatarAnim &&
          bannerAnim == other.bannerAnim &&
          supportCreds == other.supportCreds;
}
